import sys as _mbsys; _mbsys.path.insert(0, 'C:\\Users\\Nanja\\MachineBench\\machinebench\\bridge'); import mb_cam as mb
import adsk.core, adsk.fusion, adsk.cam

def run(_context):
    app = adsk.core.Application.get()
    cam = adsk.cam.CAM.cast(app.activeDocument.products.itemByProductType('CAMProductType'))
    s = cam.setups.item(0)
    print('Setup name:', s.name)
    print('operationType:', s.operationType)
    # parameters
    for p in s.parameters:
        try:
            v=p.expression
        except:
            v=None
        if any(k in p.name.lower() for k in ['stock','wcs','origin','offset','job','frame']):
            try:
                val = p.value.value
            except:
                val=None
            print(' PARAM', p.name, '=', v, '|', val)

